$ErrorActionPreference = "Stop"

$projectRoot = "D:\Projects\almustafa-connect-erp"
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$timestamp = Get-Date -Format "yyyyMMdd_HHmmss"

if (-not (Test-Path -LiteralPath $projectRoot)) {
    throw "Project folder not found: $projectRoot"
}

function Write-Base64File {
    param(
        [Parameter(Mandatory = $true)]
        [string]$RelativePath,

        [Parameter(Mandatory = $true)]
        [string]$Base64Content
    )

    $fullPath = Join-Path $projectRoot $RelativePath
    $directory = Split-Path -Parent $fullPath

    if (-not (Test-Path -LiteralPath $directory)) {
        New-Item -ItemType Directory `
            -Path $directory `
            -Force | Out-Null
    }

    if (Test-Path -LiteralPath $fullPath) {
        $backupPath = "$fullPath.teacher_leave_$timestamp.bak"
        Copy-Item -LiteralPath $fullPath `
            -Destination $backupPath `
            -Force
        Write-Host "Backup: $backupPath" `
            -ForegroundColor DarkGray
    }

    $bytes = [Convert]::FromBase64String(
        $Base64Content
    )

    $content = [Text.Encoding]::UTF8.GetString($bytes)

    [System.IO.File]::WriteAllText(
        $fullPath,
        $content,
        $utf8NoBom
    )

    Write-Host "Written: $RelativePath" `
        -ForegroundColor Green
}

Write-Host ""
Write-Host "Almustafa Connect ERP - Teacher Leave Module Setup" `
    -ForegroundColor Cyan
Write-Host ""

Write-Base64File `
    -RelativePath "lib\features\staff\presentation\teacher_leave\teacher_leave_helpers.dart" `
    -Base64Content ""

Write-Base64File `
