    -Base64Content ""

Write-Base64File `
    -RelativePath "lib\features\staff\presentation\pages\add_teacher_leave_page.dart" `
    -Base64Content ""

Write-Base64File `
    -RelativePath "lib\features\staff\presentation\pages\teacher_leave_approval_page.dart" `
    -Base64Content ""

Write-Base64File `
    -RelativePath "lib\features\staff\presentation\pages\teacher_leave_history_page.dart" `
    -Base64Content ""

Write-Base64File `
    -RelativePath "lib\features\staff\presentation\services\teacher_leave_report_service.dart" `
    -Base64Content ""

Write-Base64File `
    -RelativePath "lib\features\staff\presentation\pages\teacher_leave_report_page.dart" `
