    -Base64Content ""

Write-Base64File `
    -RelativePath "DOCS\16_TEACHER_LEAVE_MODULE.md" `
    -Base64Content ""


# ------------------------------------------------------------
# Patch Staff Dashboard
# ------------------------------------------------------------

$dashboardPath = Join-Path $projectRoot `
    "lib\features\staff\presentation\pages\staff_dashboard_page.dart"

if (-not (Test-Path -LiteralPath $dashboardPath)) {
    throw "Staff Dashboard file not found: $dashboardPath"
}

$dashboardContent =
    [System.IO.File]::ReadAllText($dashboardPath)

if (-not $dashboardContent.Contains(
    "import 'teacher_leave_page.dart';"
)) {
    $materialImport =
        "import 'package:flutter/material.dart';"

    if (-not $dashboardContent.Contains($materialImport)) {
        throw "Material import marker not found in Staff Dashboard."
    }

    $dashboardContent = $dashboardContent.Replace(
        $materialImport,
        "$materialImport`r`n`r`nimport 'teacher_leave_page.dart';"
    )
}

if (-not $dashboardContent.Contains(
    "title: 'Teacher Leave'"
)) {
    $leaveTitleIndex =
        $dashboardContent.IndexOf(
            "title: 'Leave Management'"
        )

    if ($leaveTitleIndex -lt 0) {
        throw "Leave Management card not found in Staff Dashboard."
    }

    $cardStart =
        $dashboardContent.LastIndexOf(
            "_StaffDashboardCard(",
            $leaveTitleIndex
        )

    if ($cardStart -lt 0) {
        throw "Leave Management card start not found."
    }

    $teacherCard = @'
                                _StaffDashboardCard(
                                  title: 'Teacher Leave',
                                  description:
                                      'Create, approve and review teacher leave requests.',
                                  icon: Icons.school_outlined,
                                  actionLabel: 'Open Teacher Leave',
                                  onTap: () {
                                    Navigator.of(context).push<void>(
                                      MaterialPageRoute<void>(
                                        builder: (_) =>
                                            const TeacherLeavePage(),
                                      ),
                                    );
                                  },
                                ),
'@

    $dashboardContent =
        $dashboardContent.Insert(
            $cardStart,
            $teacherCard
        )
}

$dashboardBackup =
    "$dashboardPath.teacher_leave_$timestamp.bak"

Copy-Item -LiteralPath $dashboardPath `
    -Destination $dashboardBackup `
    -Force

[System.IO.File]::WriteAllText(
    $dashboardPath,
    $dashboardContent,
    $utf8NoBom
)

Write-Host "Updated: Staff Dashboard" `
    -ForegroundColor Green

# ------------------------------------------------------------
# Patch Approved Leave Attendance Remark
# ------------------------------------------------------------

$updateStatusPath = Join-Path $projectRoot `
    "lib\features\staff\domain\usecases\update_staff_leave_status.dart"

if (-not (Test-Path -LiteralPath $updateStatusPath)) {
    throw "UpdateStaffLeaveStatus file not found."
}

$updateStatusContent =
    [System.IO.File]::ReadAllText($updateStatusPath)

$oldOtherLine =
    "      StaffLeaveType.other => 'Other Leave',"

$newOtherLine =
    "      StaffLeaveType.other =>`r`n" +
    "        leave.designation.toLowerCase().contains('teacher')`r`n" +
    "            ? 'Leave'`r`n" +
    "            : 'Other Leave',"

if ($updateStatusContent.Contains($oldOtherLine)) {
    $updateStatusBackup =
        "$updateStatusPath.teacher_leave_$timestamp.bak"

    Copy-Item -LiteralPath $updateStatusPath `
        -Destination $updateStatusBackup `
        -Force

    $updateStatusContent =
        $updateStatusContent.Replace(
            $oldOtherLine,
            $newOtherLine
        )

    [System.IO.File]::WriteAllText(
        $updateStatusPath,
        $updateStatusContent,
        $utf8NoBom
    )

    Write-Host `
        "Updated: Teacher Leave attendance remark" `
        -ForegroundColor Green
} elseif (-not $updateStatusContent.Contains(
    "? 'Leave'"
)) {
    throw "Unable to patch Teacher Leave attendance remark."
} else {
    Write-Host `
        "Attendance remark already configured." `
        -ForegroundColor Yellow
}

