    "lib\features\staff\presentation\pages\teacher_leave_history_page.dart",
    "lib\features\staff\presentation\pages\teacher_leave_report_page.dart",
    "lib\features\staff\presentation\services\teacher_leave_report_service.dart",
    "lib\features\staff\presentation\pages\staff_dashboard_page.dart",
    "lib\features\staff\domain\usecases\update_staff_leave_status.dart"
)

Push-Location $projectRoot

try {
    Write-Host ""
    Write-Host "Formatting Dart files..." `
        -ForegroundColor Cyan

    & dart format $dartFiles

    if ($LASTEXITCODE -ne 0) {
        throw "dart format failed."
    }

    Write-Host ""
    Write-Host "Running flutter analyze..." `
        -ForegroundColor Cyan

    & flutter analyze

    if ($LASTEXITCODE -ne 0) {
        throw "flutter analyze found issues. Review output above."
    }
}
finally {
    Pop-Location
}

